import assert from 'node:assert/strict';import {writeFile,readFile} from 'node:fs/promises';
export const name='tokenlog-mounted-probe';export const inject=['tokenlog','tools'];
export async function apply(ctx){
  try{const tool=ctx.tools.get('token_usage_summary');assert.ok(tool);const raw=await ctx.tokenlog.aggregate(undefined,7);assert.equal(raw.availability.status,'complete');const result=await ctx.tools.execute({callId:'t07-mounted',name:'token_usage_summary',arguments:{days:7},signal:new AbortController().signal});assert.equal(result.isError,false);assert.ok(result.content[0].text.includes('按任务'));assert.ok(result.content[0].text.includes('原生身份'));assert.ok(result.content[0].text.includes('关键词推断'));const fields=['input','output','messages','cacheRead','cacheWrite','cacheReadRecords','cacheWriteRecords'];for(const field of fields)assert.equal(Object.values(raw.byTask).reduce((n,r)=>n+r[field],0),raw.details[field]);
    let mobile;
    if(process.env.T07_HMC_MODULE){const {dshAdapter}=await import(process.env.T07_HMC_MODULE);const adapter=dshAdapter({get:name=>name==='tokenlog'?ctx.tokenlog:undefined,connection:{createSharedFetchHandler:()=>({fetch(){throw Error('Unexpected upstream call')}})}});mobile=(await adapter.call('muse/usage/summary',{})).value;assert.equal(mobile.totals.input,50);assert.equal(mobile.byTask.find(r=>r.id==='native_task').sessions,2);assert.equal(mobile.details.cacheReadRecords,4);assert.equal(mobile.byModel.find(r=>r.id==='actual/fallback').input,10);assert.doesNotMatch(JSON.stringify(mobile),/PRIVATE/);}
    const file=process.env.T07_ROOT+'/unknown/session.v4.jsonl.zstd',original=await readFile(file);await writeFile(file,'bad compressed');
    const toolFailure=await ctx.tools.execute({callId:'t07-bad-source',name:'token_usage_summary',arguments:{days:7},signal:new AbortController().signal});assert.equal(toolFailure.isError,true);assert.equal(toolFailure.error.info.code,'TOKENLOG_DECOMPRESS_FAILED');assert.match(toolFailure.content[0].text,/TOKENLOG_DECOMPRESS_FAILED/);await writeFile(file,original);
    const aborted=new AbortController();aborted.abort();const toolCancelled=await ctx.tools.execute({callId:'t07-cancelled',name:'token_usage_summary',arguments:{days:7},signal:aborted.signal});assert.equal(toolCancelled.isError,true);
    const summary={totals:{input:raw.details.input,output:raw.details.output},classifications:Object.values(raw.byTask).map(r=>r.classification).sort(),scope:'unclassified',actualModels:Object.keys(raw.byModel).sort(),cacheRecorded:raw.details.cacheReadRecords,duplicateRootCounted:raw.sessions!==5,sourceFailureIsError:toolFailure.isError,cancelledIsError:toolCancelled.isError};assert.deepEqual(summary,JSON.parse(await readFile(new URL('../expected/mounted-usage.json',import.meta.url),'utf8')));console.log('MOUNTED_USAGE '+JSON.stringify({...summary,hmcRead:!!mobile}));
    await writeFile(process.env.T07_RECEIPT,JSON.stringify({ok:true,raw,result,mobile,toolFailure,toolCancelled})+'\n');}
  catch(error){await writeFile(process.env.T07_RECEIPT,JSON.stringify({ok:false,message:error.message})+'\n');}
}
